$\begin{aligned}
& \left(\mathrm{CH}_3\right)_3 \mathrm{CONa}+\mathrm{CH}_3 \mathrm{CH}_2 \mathrm{Br} \rightarrow \mathrm{X} \\
& \left(\mathrm{CH}_3\right)_3 \mathrm{CBr}+\mathrm{CH}_3 \mathrm{CH}_2 \mathrm{ONa} \rightarrow \mathrm{Y}
\end{aligned}$

